import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------------------------------------------------------
# CUDA source for a simple fp16 3‑D convolution (stride=1, padding=0,
# dilation=1, groups=1, bias optional). Accumulation is performed in fp32.
# ------------------------------------------------------------------
cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <int BLOCK_SIZE>
__global__ void conv3d_fp16_kernel(
    const half* __restrict__ input,
    const half* __restrict__ weight,
    const half* __restrict__ bias,
    half* __restrict__ output,
    int batch,
    int in_channels,
    int out_channels,
    int D, int H, int W,
    int K,
    int stride,
    int padding,
    int dilation,
    int D_out,
    int H_out,
    int W_out)
{
    const int idx = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int total = batch * out_channels * D_out * H_out * W_out;
    if (idx >= total) return;

    // unravel linear index
    int w_out = idx % W_out;
    int tmp  = idx / W_out;
    int h_out = tmp % H_out;
    tmp      = tmp / H_out;
    int d_out = tmp % D_out;
    int oc    = (tmp / D_out) % out_channels;
    int n     = tmp / (D_out * out_channels);

    float sum = 0.0f;

    // iterate over input channels and kernel volume
    for (int ic = 0; ic < in_channels; ++ic) {
        for (int kd = 0; kd < K; ++kd) {
            int d_in = d_out * stride - padding + kd * dilation;
            if (d_in < 0 || d_in >= D) continue;
            for (int kh = 0; kh < K; ++kh) {
                int h_in = h_out * stride - padding + kh * dilation;
                if (h_in < 0 || h_in >= H) continue;
                for (int kw = 0; kw < K; ++kw) {
                    int w_in = w_out * stride - padding + kw * dilation;
                    if (w_in < 0 || w_in >= W) continue;

                    int input_idx = (((((n * in_channels + ic) * D + d_in) * H) + h_in) * W) + w_in;
                    int weight_idx = (((((oc * in_channels + ic) * K + kd) * K) + kh) * K) + kw;

                    sum += __half2float(input[input_idx]) *
                           __half2float(weight[weight_idx]);
                }
            }
        }
    }

    if (bias != nullptr) {
        sum += __half2float(bias[oc]);
    }

    output[idx] = __float2half(sum);
}

// ------------------------------------------------------------------
// Launcher
// ------------------------------------------------------------------
torch::Tensor conv3d_fp16(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation)
{
    // sanity checks
    TORCH_CHECK(input.is_cuda() && weight.is_cuda(), "input and weight must be CUDA tensors");
    TORCH_CHECK(input.dtype() == torch::kHalf && weight.dtype() == torch::kHalf,
                "Only fp16 tensors are supported");
    if (bias.defined()) {
        TORCH_CHECK(bias.is_cuda() && bias.dtype() == torch::kHalf, "bias must be CUDA fp16");
    }

    const int batch      = input.size(0);
    const int in_chan    = input.size(1);
    const int D_in       = input.size(2);
    const int H_in       = input.size(3);
    const int W_in       = input.size(4);

    const int out_chan   = weight.size(0);
    const int K          = weight.size(2); // kernel depth = height = width

    // output dimensions (standard conv formula)
    const int D_out = (D_in + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int H_out = (H_in + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int W_out = (W_in + 2 * padding - dilation * (K - 1) - 1) / stride + 1;

    auto options = torch::TensorOptions()
                       .dtype(torch::kHalf)
                       .device(input.device())
                       .requires_grad(input.requires_grad() ||
                                      weight.requires_grad() ||
                                      (bias.defined() && bias.requires_grad()));
    torch::Tensor output = torch::empty({batch, out_chan, D_out, H_out, W_out}, options);

    const int total = batch * out_chan * D_out * H_out * W_out;
    const int BLOCK_SIZE = 256;
    const int grid = (total + BLOCK_SIZE - 1) / BLOCK_SIZE;

    const half* input_ptr = reinterpret_cast<const half*>(input.data_ptr<torch::Half>());
    const half* weight_ptr = reinterpret_cast<const half*>(weight.data_ptr<torch::Half>());
    const half* bias_ptr = bias.defined() ? reinterpret_cast<const half*>(bias.data_ptr<torch::Half>()) : nullptr;
    half* output_ptr = reinterpret_cast<half*>(output.data_ptr<torch::Half>());

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(input.scalar_type(), "conv3d_fp16_kernel", ([&] {
        conv3d_fp16_kernel<BLOCK_SIZE><<<grid, BLOCK_SIZE>>>(
            input_ptr,
            weight_ptr,
            bias_ptr,
            output_ptr,
            batch,
            in_chan,
            out_chan,
            D_in,
            H_in,
            W_in,
            K,
            stride,
            padding,
            dilation,
            D_out,
            H_out,
            W_out);
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA error: %s\\n", cudaGetErrorString(err));
    }

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv3d_fp16", &conv3d_fp16, "FP16 3D convolution (CUDA)");
}
'''

