# Compile the extension in‑line
# ------------------------------------------------------------------
conv3d_ext = load_inline(
    name='conv3d_fp16_ext',
    cpp_sources='',          # no pure C++ portion needed
    cuda_sources=cuda_src,
    functions=['conv3d_fp16'],
    verbose=False,
)

# ------------------------------------------------------------------
# PyTorch module that uses the custom kernel
# ------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model using a custom CUDA kernel.
    Supports only stride=1, padding=0, dilation=1, groups=1, bias=False/True.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 groups: int = 1,
                 bias: bool = False):
        super().__init__()
        assert groups == 1, "Only groups=1 is supported in this custom implementation"
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.kernel_size = kernel_size

        weight_shape = (out_channels, in_channels, kernel_size, kernel_size, kernel_size)
        self.weight = nn.Parameter(torch.empty(weight_shape, dtype=torch.float16, device='cuda'))
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)   # same init as nn.Conv3d

        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels, dtype=torch.float16, device='cuda'))
            fan_in = in_channels * kernel_size * kernel_size * kernel_size
            bound = 1 / fan_in**0.5
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.bias = None

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("ModelNew only supports CUDA tensors")
        if x.dtype != torch.float16:
            raise RuntimeError("ModelNew only supports fp16 tensors")
        return conv3d_ext.conv3d_fp16(
            x,
            self.weight,
            self.bias if self.bias is not None else torch.tensor([], dtype=torch.float16, device='cuda'),
            self.stride,
            self.padding,
            self.dilation,
        )

# ------------------------------------------------------------------
# Example usage / test harness (mirrors the original reference)
# ------------------------------------------------------------------
if __name__ == "__main__":
    batch_size = 16
    in_channels = 3
    out_channels = 64
    kernel_size = 3
    depth = 64
    width = 64
    height = 64

    model = ModelNew(in_channels, out_channels, kernel_size).cuda().half()
    x = torch.rand(batch_size, in_channels, depth, width, height, dtype=torch.float16, device='cuda')
    y = model(x)
    print('output shape:', y.shape)
